let markdown = $json.rawMarkdown;

// Remove ```markdown wrappers if present
markdown = markdown.replace(/```markdown/g, '');
markdown = markdown.replace(/```/g, '');

return [{ json: { cleanedMarkdown: markdown } }];

// Detect AI output safely across all n8n versions

let text = "";

// Case 1: Newer n8n format
if ($json.output_text) {
  text = $json.output_text;
}

// Case 2: Direct string output
else if (typeof $json.output === "string") {
  text = $json.output;
}

// Case 3: Array structured output
else if ($json.output?.[0]?.content?.[0]?.text) {
  text = $json.output[0].content[0].text;
}

// Case 4: message.content format
else if ($json.message?.content) {
  text = $json.message.content;
}

// If still empty, throw real debug info
if (!text || text.trim().length < 50) {
  throw new Error("AI returned unexpected structure: " + JSON.stringify($json));
}

return [
  {
    json: {
      rawMarkdown: text
    }
  }
];

